 (id,company_id,event_type,severity,event_date,location,description,immediate_action,reported_by,assigned_to,action_due_date,status,event_ref,department,person_involved,incident_subtype,incident_number,lost_time_days,investigation_required,investigation_ref,site_id,site_name_snapshot,title,potential_severity,likelihood,confidentiality,immediate_danger,reporter_mode,work_activity,triage_status,investigation_level,target_closure_date,submitted_at) values
 ('b4300000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','near_miss','high','2026-07-21 10:15+04','Bagasse Yard crossing','Loader reversed toward a sampling technician at the marked pedestrian crossing; the banksman stopped the movement before contact.','Stopped operation, isolated route and briefed loader team.','Rahul Mootoosamy','Kavish Beeharry','2026-08-15','under_investigation','EV-BC-2026-017','Logistics','No injury','vehicle_near_miss','INC-BC-2026-017',0,true,'INV-BC-2026-006','b2000000-0000-4000-8000-000000000004','Bagasse Yard & Fuel Handling','Loader–pedestrian near miss at bagasse crossing','critical','possible','internal',false,'named','Bagasse sampling and stockpile management','investigation_required','full','2026-08-31','2026-07-21 10:35+04'),
