insert into public.investigations
 (id,company_id,event_id,title,incident_date,location,investigated_by,persons_involved,what_happened,immediate_causes,human_factors,technical_conditions,root_causes,corrective_actions,preventive_actions,lessons_learned,status,inv_ref,inv_type,department,investigation_method,investigation_lead,team_members,start_date,target_completion,five_whys,contributing_factors,systemic_causes,severity_actual,severity_potential,likelihood_recurrence,plan_status,plan_version,objective,scope,reviewer_name,confidentiality,completeness_json) values
 ('b4310000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','b4300000-0000-4000-8000-000000000001','Bagasse yard loader–pedestrian near miss','2026-07-21 10:15+04','Bagasse Yard crossing','Vikash Nundlall','Rahul Mootoosamy; loader operator; banksman','Sampling technician entered the crossing while the loader was reversing from the stockpile. The banksman intervened.','Line of sight partially obstructed; crossing release not positively confirmed.','Routine familiarity reduced challenge of an ambiguous radio message.','Dust and stockpile geometry reduced visibility.','Traffic plan did not require positive confirmation before crossing entry.','Introduce positive radio protocol and temporary crossing marshal.','Install blue warning projection and review yard one-way route.','Engineering separation must not rely only on reversing alarms.','in_progress','INV-BC-2026-006','full','HSE','5why','Vikash Nundlall','Elodie Wong, Kavish Beeharry','2026-07-22','2026-08-31','["Why was the pedestrian in the reversing zone? Crossing entry occurred before positive release.","Why was release unclear? Radio phrase was not standardised.","Why no standard phrase? Traffic plan relied on informal coordination.","Why was informal coordination accepted? Previous reviews focused on alarms rather than crossing control.","Why? Critical-control verification did not include pedestrian release protocol."]','Dust, stockpile height and shift-change congestion.','Traffic management assurance did not test the crossing-release control.','near_miss','fatal','possible','approved',1,'Identify direct, contributing and systemic causes and verify sustainable controls.','Bagasse yard traffic route, crossing, supervision and communications.','Aisha Raman','internal','{"plan":true,"evidence":true,"analysis":true,"actions":true}')
