insert into public.emergency_plans
 (id,company_id,plan_ref,title,emergency_type,severity_level,scope,site_name,location,version,status,approved_by,approved_date,review_date,last_tested,objectives,activation_criteria,immediate_actions,escalation_procedure,resource_requirements,communication_plan,recovery_actions,lessons_from_tests,key_contacts,resources) values
 ('b6300000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','ERP-BC-001','Fire and explosion response — sugar mill and power house','fire','critical','All process areas, bagasse yard, boiler house and turbine hall','Belle Rive Sugar & Energy Complex','Belle Rive','2.1','active','Aisha Raman','2026-06-01','2027-06-01','2026-07-15','Protect life, account for all persons, isolate energy and support emergency services.','Confirmed fire, explosion, uncontrolled smoke or automatic suppression discharge.','Raise alarm; call control room; stop work; evacuate by marked routes; wardens sweep only if safe.','Control room notifies incident commander, site manager and emergency services; HSE manager starts accountability.','Fire pumps, hydrants, foam stock, first aid, radios, emergency generator and spill control.','PA announcement, radio channel 1, in-app alert and external emergency call.','Preserve scene, verify structural and process integrity, environmental monitoring and controlled restart.','July drill showed muster scanning was faster than paper list but visitor briefing required improvement.','[{"role":"Incident commander","name":"Jean-Luc Morel","phone":"DEMO"},{"role":"HSE lead","name":"Vikash Nundlall","phone":"DEMO"}]','[{"item":"Fire pump","location":"Pump house"},{"item":"Foam trailer","location":"Power House east"},{"item":"AED","location":"Medical Centre"}]'),
 ('b6300000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000001','ERP-BC-002','Cyclone and grid-loss continuity response','power_failure','major','Power generation, critical sugar process and safe shutdown','Belle Rive Sugar & Energy Complex','Main control room','1.3','active','Aisha Raman','2026-05-20','2027-05-20','2026-05-25','Maintain safe shutdown, emergency power and communication during grid loss or severe weather.','Grid instability, cyclone warning class escalation, loss of two critical feeders or black-start demand.','Stabilise boilers, protect turbine, start emergency generation and suspend non-essential work.','Control-room escalation to power manager and general manager; notify grid operator.','Black-start diesel, UPS, radios, minimum staffing and protected fuel reserve.','Control room log, radio, SMS and in-app incident channel.','Inspect critical assets before synchronisation and staged restart.','Tabletop test confirmed black-start checklist; update contractor callout list.','[{"role":"Power manager","name":"Jean-Luc Morel","phone":"DEMO"}]','[{"item":"Emergency generator","location":"Power House"},{"item":"Black-start checklist","location":"Control room"}]')
