 ('b7100000-0000-4000-8000-000000000003','b1000000-0000-4000-8000-000000000001','BC-STEAM-01','High-Pressure Steam Release Awareness','Process safety','OSHA incident-learning video for boiler and turbine personnel.',2,80,'https://www.youtube.com/watch?v=ij3HN6fVxLA',true,'{supervisor,employee}',12,'active',2,true,'[{"id":"steam-osha","sequence":1,"title":"OSHA: High Pressure / Temperature Steam Release","video_url":"https://www.youtube.com/watch?v=ij3HN6fVxLA","duration_minutes":2}]','{"enabled":true,"passing_score":80,"questions":[{"id":"q1","prompt":"Before opening steam equipment, what is essential?","options":["Isolation, depressurisation and temperature verification","Only gloves","A verbal estimate"],"correct_index":0}]}')
