begin;

do $safety$
begin
  if exists (
    select 1 from public.companies
    where lower(name) = 'buildco mauritius'
      and id <> 'b1000000-0000-4000-8000-000000000001'::uuid
  ) then
    raise exception 'A non-showcase company named BuildCo Mauritius already exists; seed stopped.';
  end if;
end
$safety$;

