-- Verification summary returned by the Supabase SQL Editor.
select c.id,c.name,c.industry,c.headcount,
  (select count(*) from public.sites s where s.company_id=c.id) as sites,
  (select count(*) from public.people p where p.company_id=c.id) as people,
  (select count(*) from public.tools_register t where t.company_id=c.id) as tools_and_vehicles,
  (select count(*) from public.elearning_courses e where e.company_id=c.id) as video_courses,
  (select count(*) from public.risk_assessments r where r.company_id=c.id) as risk_assessments,
  (select count(*) from public.action_tracker a where a.company_id=c.id) as tracked_actions
from public.companies c
where c.id='b1000000-0000-4000-8000-000000000001';
